update T_XWYY_BG_RUB_CAR_RELATION
big_roll_code = #{bigRollCode}, rubber_code = #{rubberCode}, car_number = #{carNumber}, del_flag = #{delFlag}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, remark = #{remark},
where id = #{id}

