mapper.update:
merge into T_XWYY_BG_RUB_CAR_RELATION a USING (
select #{bigRollRubberCarRelation.bigRollCode,jdbcType=VARCHAR} big_roll_code, #{bigRollRubberCarRelation.rubberCode,jdbcType=VARCHAR} rubber_code, #{bigRollRubberCarRelation.carNumber,jdbcType=VARCHAR} car_number, #{bigRollRubberCarRelation.createBy,jdbcType=VARCHAR} create_by, #{bigRollRubberCarRelation.createTime,jdbcType=DATE} create_time, #{bigRollRubberCarRelation.updateBy,jdbcType=VARCHAR} update_by, #{bigRollRubberCarRelation.updateTime,jdbcType=DATE} update_time, #{bigRollRubberCarRelation.remark,jdbcType=VARCHAR} remark from dual
) b ON ( a.big_roll_code = b.big_roll_code AND a.del_flag = '0' ) WHEN MATCHED THEN UPDATE SET a.rubber_code = b.rubber_code, a.car_number = b.car_number, a.update_by = b.create_by, a.update_time = sysdate, a.remark = b.remark WHEN NOT MATCHED THEN INSERT ( a.id , a.big_roll_code , a.rubber_code, a.car_number, a.create_by , a.create_time , a.remark, a.del_flag ) values (SEQ_XWYY_BG_RUB_CAR_RELATION.NEXTVAL, b.big_roll_code , b.rubber_code, b.car_number, b.create_by, sysdate, b.remark, '0' )
